css:
.frow > .fc { display:block; margin-top:4px; padding:1px 0 1px 9px;
              border-left:3px solid; background:#faf7fe; border-radius:0 8px 8px 0;
              line-height:1.4; }

/* A LIST PANEL — reagents, or uses. Not formulae, so not boxes.
   Each row is `thing — what it is for`: the thing keeps the notation
   face, the description is prose, and a hairline separates the rows.
   Six coloured boxes for a list of solvents read as six formulae to
   memorise, which is what looked wrong about it. */
.fcard--list>.frow { margin:0; padding:5px 0; border-top:1px solid #e8e4d6; }
.fcard--list>.frow:first-of-type { border-top:0; }
.fcard--list .fx { border:0 !important; background:none !important;
     padding:0 !important; box-shadow:none !important;
     display:inline !important; }
.fcard--list .fcap { font-style:normal; opacity:.95; }
.fcard--list { background:none; border-style:dashed; border-width:1px; }
